        let t:     int = total / 3;  // floor division
        let rg:    int = r_i + g_i;
        let rb:    int = r_i + b_i;
        let gb:    int = g_i + b_i;

        // Take the minimum of the four
        let m1: int = if t < rg { t } else { rg };
        let m2: int = if rb < gb { rb } else { gb };
        let res_i: int = if m1 < m2 { m1 } else { m2 };

        // Prove the cast back to i8 is safe:
